<?php
declare(strict_types=1);require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/auth.php';require_once __DIR__.'/../../src/ui.php';$user=require_student();$pdo=db();
$stmt=$pdo->prepare("SELECT COALESCE(sp.overall_level,'PRE-A1') overall_level,COALESCE(sp.goal,'Aprender inglês') goal,COALESCE(p.conversation_topic,'daily_life') conversation_topic,COALESCE(p.conversation_style,'guided') conversation_style,COALESCE(p.conversation_max_turns,10) conversation_max_turns,COALESCE(p.correction_mode,sp.correction_mode,'balanced') correction_mode FROM students s LEFT JOIN student_profiles sp ON sp.student_id=s.id LEFT JOIN student_preferences p ON p.student_id=s.id WHERE s.id=:id");$stmt->execute(['id'=>$user['student_id']]);$settings=$stmt->fetch()?:[];
$active=$pdo->prepare("SELECT COALESCE(conversation_topic,topic,'daily_life') topic,COALESCE(conversation_style,'guided') style,COALESCE(turn_count,0) turn_count,COALESCE(max_turns,10) max_turns FROM sessions WHERE student_id=:id AND status='active' AND mode='conversation' ORDER BY created_at DESC LIMIT 1");$active->execute(['id'=>$user['student_id']]);$session=$active->fetch()?:null;
$topic=$session['topic']??$settings['conversation_topic']??'daily_life';$style=$session['style']??$settings['conversation_style']??'guided';$maxTurns=(int)($session['max_turns']??$settings['conversation_max_turns']??10);$correction=$settings['correction_mode']??'balanced';
$pageTitle='Praticar com Emma';$pageSubtitle='Escolha o tema e pratique por texto ou áudio.';require __DIR__.'/../../templates/header.php';?>
<section class="practice-shell"><div class="practice-main"><section class="panel voice-practice"><div class="conversation-settings"><div><label for="conversation-topic">Tema</label><select id="conversation-topic"><?php foreach(['daily_life'=>'Rotina e dia a dia','work'=>'Trabalho e carreira','technology'=>'Tecnologia','travel'=>'Viagem','food'=>'Comida e restaurante','movies'=>'Filmes e séries','goals'=>'Planos e objetivos','job_interview'=>'Entrevista de emprego','free_conversation'=>'Conversação livre'] as $value=>$label):?><option value="<?=e($value)?>" <?=$topic===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div><label for="conversation-style">Formato</label><select id="conversation-style"><option value="guided" <?=$style==='guided'?'selected':''?>>Guiada</option><option value="free" <?=$style==='free'?'selected':''?>>Livre</option><option value="roleplay" <?=$style==='roleplay'?'selected':''?>>Simulação</option></select></div><div><label for="correction-mode">Correções</label><select id="correction-mode"><option value="light" <?=$correction==='light'?'selected':''?>>Leves</option><option value="balanced" <?=$correction==='balanced'?'selected':''?>>Equilibradas</option><option value="intensive" <?=$correction==='intensive'?'selected':''?>>Intensivas</option></select></div><div><label for="conversation-max-turns">Duração</label><select id="conversation-max-turns"><?php foreach([6,10,14] as $n):?><option value="<?=$n?>" <?=$maxTurns===$n?'selected':''?>><?=$n?> interações</option><?php endforeach;?></select></div></div><p class="conversation-hint">A Emma corrige em português quando necessário e mantém a continuidade da conversa em inglês.</p><div class="practice-tabs"><button class="btn btn-primary" type="button" data-tab-button="text">Digitar</button><button class="btn btn-secondary" type="button" data-tab-button="voice">Conversar por áudio</button></div><div data-tab-panel="text"><div id="chat" class="voice-chat"><div class="chat-message teacher"><strong>Emma</strong><p>Hello, <?=e(ui_first_name($user['name']))?>! Choose a topic and send your first message.</p></div></div><form id="practice-form" class="practice-compose"><input id="message" autocomplete="off" placeholder="Escreva em inglês..." required><button class="btn btn-primary">Enviar</button></form></div><div data-tab-panel="voice" hidden><div class="voice-recorder"><div class="voice-status"><span id="voice-dot" class="record-dot"></span><strong id="voice-status-text">Pronto para gravar</strong><span id="voice-timer" class="badge">00:00</span></div><div class="voice-actions"><button id="start-recording" class="btn btn-primary" type="button">Iniciar gravação</button><button id="stop-recording" class="btn btn-secondary" type="button" disabled>Parar</button><button id="discard-recording" class="btn btn-secondary" type="button" disabled>Descartar</button></div><audio id="recording-preview" controls hidden></audio><button id="send-recording" class="btn btn-primary" type="button" disabled>Enviar para Emma</button></div><div id="voice-result" hidden><div class="list-card"><strong>Você disse</strong><p id="student-transcription"></p></div><div class="list-card"><strong>Emma respondeu</strong><p id="teacher-response"></p><audio id="teacher-audio" controls></audio></div></div></div></section></div><aside class="practice-sidebar"><section class="panel"><h2>Sua prática</h2><div class="info-grid"><div class="info-item"><span>Nível</span><strong><?=e($settings['overall_level']??'PRE-A1')?></strong></div><div class="info-item"><span>Correção</span><strong><?=e(ui_status_label($correction))?></strong></div><div class="info-item"><span>Interações</span><strong><?= (int)($session['turn_count']??0)?>/<?=$maxTurns?></strong></div><div class="info-item"><span>Formato</span><strong><?=e(ui_status_label($style))?></strong></div></div></section><section class="panel"><h2>Dicas</h2><div class="list-card"><strong>Responda com frases completas</strong><p>Mesmo frases curtas ajudam a Emma a avaliar sua evolução.</p></div><div class="list-card"><strong>Peça ajuda quando precisar</strong><p>Escreva “não entendi” e a Emma explicará em português.</p></div><div class="list-card"><strong>Use o áudio</strong><p>Pratique ritmo e naturalidade sem se preocupar com perfeição.</p></div></section></aside></section>
